import { createEnv } from "@t3-oss/env-core";
import { z } from "zod";

export const env = createEnv({
  server: {
    PORT: z.coerce.number().default(5555),
    /**
     * This secret is configured via a Docker Secret, the env var itself is just
     * a file handle.
     * 
     * The secret itself can be generated by:

     * openssl rand -hex 32
     */
    AUTH_SECRET_FILE: z.string().nonempty(),
    OAUTH_CLIENT_ID: z.string().nonempty(),
    OAUTH_CLIENT_SECRET_FILE: z.string().nonempty(),
    OAUTH_ISSUER: z.string().nonempty(),
    BETTER_AUTH_TRUSTED_ORIGINS: z.string().nonempty(),
  },

  client: {
    VITE_BASE_URL: z.url(),
  },

  clientPrefix: "VITE_",

  /**
   * What object holds the environment variables at runtime. This is usually
   * `process.env` or `import.meta.env`.
   */
  runtimeEnv: {
    PORT: process.env.PORT,
    AUTH_SECRET_FILE: process.env.AUTH_SECRET_FILE,
    OAUTH_CLIENT_ID: process.env.OAUTH_CLIENT_ID,
    OAUTH_CLIENT_SECRET_FILE: process.env.OAUTH_CLIENT_SECRET_FILE,
    OAUTH_ISSUER: process.env.OAUTH_ISSUER,
    BETTER_AUTH_TRUSTED_ORIGINS: process.env.BETTER_AUTH_TRUSTED_ORIGINS,
    VITE_BASE_URL: process.env.VITE_BASE_URL,
  },

  /**
   * By default, this library will feed the environment variables directly to
   * the Zod validator.
   *
   * This means that if you have an empty string for a value that is supposed
   * to be a number (e.g. `PORT=` in a ".env" file), Zod will incorrectly flag
   * it as a type mismatch violation. Additionally, if you have an empty string
   * for a value that is supposed to be a string with a default value (e.g.
   * `DOMAIN=` in an ".env" file), the default value will never be applied.
   *
   * In order to solve these issues, we recommend that all new projects
   * explicitly specify this option as true.
   */
  emptyStringAsUndefined: true,
});
